import numpy as np

def polygon_properties(vertices):
    v = np.asarray(vertices, dtype=np.float64)
    if v.ndim != 2 or v.shape[1] != 2:
        raise ValueError("vertices must have shape (N, 2)")
    if v.shape[0] < 3:
        return (0.0, 0.0, 0.0)
    if not np.isfinite(v).all():
        raise ValueError("vertices must be finite")

    x = v[:, 0]
    y = v[:, 1]
    x_next = np.roll(x, -1)
    y_next = np.roll(y, -1)
    cross = x * y_next - x_next * y

    area = 0.5 * float(cross.sum())
    if np.isclose(area, 0.0):
        return (area, 0.0, 0.0)

    cx = float(((x + x_next) * cross).sum() / (6.0 * area))
    cy = float(((y + y_next) * cross).sum() / (6.0 * area))
    return (area, cx, cy)

import numpy as np

def extract_keypoints(heatmaps: np.ndarray, gt_keypoints: np.ndarray, threshold: float = 0.1) -> np.ndarray:
    hm = np.asarray(heatmaps)
    gt = np.asarray(gt_keypoints)

    if hm.ndim == 3:
        hm = hm[:, None, :, :]
    if hm.ndim != 4:
        raise ValueError("heatmaps must have shape (N,H,W) or (N,K,H,W)")

    n, k, h, w = hm.shape
    if gt.shape != (n, k, 2):
        raise ValueError("gt_keypoints must have shape (N,K,2)")

    out = np.full((n, k, 2), np.nan, dtype=np.float64)

    def at(patch, rr, cc):
        if 0 <= rr < 3 and 0 <= cc < 3:
            return float(patch[rr, cc])
        return 0.0

    for bi in range(n):
        for ki in range(k):
            xg, yg = gt[bi, ki]
            if not (np.isfinite(xg) and np.isfinite(yg)):
                continue
            xg, yg = int(xg), int(yg)

            patch = np.zeros((3, 3), dtype=np.float64)
            for rr, yy in enumerate(range(yg - 1, yg + 2)):
                if yy < 0 or yy >= h:
                    continue
                for cc, xx in enumerate(range(xg - 1, xg + 2)):
                    if 0 <= xx < w:
                        patch[rr, cc] = hm[bi, ki, yy, xx]

            flat = int(np.argmax(patch))
            r, c = divmod(flat, 3)
            peak = float(patch[r, c])
            if peak < threshold:
                continue

            xp = xg + c - 1
            yp = yg + r - 1

            vl, vr = at(patch, r, c - 1), at(patch, r, c + 1)
            vt, vb = at(patch, r - 1, c), at(patch, r + 1, c)
            den_x = vl - 2.0 * peak + vr
            den_y = vt - 2.0 * peak + vb

            dx = 0.0 if abs(den_x) < 1e-6 else 0.5 * (vl - vr) / den_x
            dy = 0.0 if abs(den_y) < 1e-6 else 0.5 * (vt - vb) / den_y

            dx = float(np.clip(dx, -0.5, 0.5))
            dy = float(np.clip(dy, -0.5, 0.5))
            out[bi, ki] = (xp + dx, yp + dy)

    return out

