import numpy as np

def rotated_box_intersection(box1: tuple, box2: tuple) -> float:
    def corners(box):
        if len(box) != 5:
            raise ValueError("each box must be (cx, cy, w, h, theta)")
        cx, cy, w, h, theta = map(float, box)
        if w < 0 or h < 0:
            raise ValueError("width and height must be non-negative")
        hw, hh = w / 2.0, h / 2.0
        local = np.array([[-hw, -hh], [hw, -hh], [hw, hh], [-hw, hh]], dtype=np.float64)
        c, s = math.cos(theta), math.sin(theta)
        R = np.array([[c, -s], [s, c]], dtype=np.float64)
        return local @ R.T + np.array([cx, cy], dtype=np.float64)

    def cross(a, b):
        return a[0] * b[1] - a[1] * b[0]

    def inside(p, a, b):
        return cross(b - a, p - a) >= -1e-12

    def intersection(p1, p2, a, b):
        r = p2 - p1
        s = b - a
        den = cross(r, s)
        if abs(den) < 1e-15:
            return p2.copy()
        t = cross(a - p1, s) / den
        return p1 + t * r

    subject = [p.copy() for p in corners(box1)]
    clipper = corners(box2)

    for i in range(4):
        a = clipper[i]
        b = clipper[(i + 1) % 4]
        inp = subject
        subject = []
        if not inp:
            break
        prev = inp[-1]
        prev_in = inside(prev, a, b)
        for cur in inp:
            cur_in = inside(cur, a, b)
            if cur_in:
                if not prev_in:
                    subject.append(intersection(prev, cur, a, b))
                subject.append(cur)
            elif prev_in:
                subject.append(intersection(prev, cur, a, b))
            prev, prev_in = cur, cur_in

    if len(subject) < 3:
        return 0.0

    poly = np.asarray(subject, dtype=np.float64)
    area = 0.5 * abs(
        np.dot(poly[:, 0], np.roll(poly[:, 1], -1))
        - np.dot(poly[:, 1], np.roll(poly[:, 0], -1))
    )
    return float(area)

