import torch

def clip_grads_by_global_norm(grads: list, max_norm: float) -> tuple:
    if max_norm < 0:
        raise ValueError("max_norm must be non-negative")
    if len(grads) == 0:
        return 0.0, []

    sq_sum = 0.0
    for g in grads:
        if not isinstance(g, torch.Tensor):
            raise TypeError("all gradients must be torch tensors")
        n = torch.linalg.vector_norm(g.detach().double()).item()
        sq_sum += n * n

    total_norm = math.sqrt(sq_sum)

    if total_norm == 0.0 or total_norm <= max_norm:
        return total_norm, [g.clone() for g in grads]

    scale = max_norm / total_norm
    return total_norm, [g * scale for g in grads]

import numpy as np

def compute_ece(probs: np.ndarray, labels: np.ndarray, n_bins: int) -> float:
    p = np.asarray(probs, dtype=np.float64)
    y = np.asarray(labels)

    if p.ndim != 1 or y.ndim != 1 or p.shape != y.shape:
        raise ValueError("probs and labels must be same-shaped 1D arrays")
    if not isinstance(n_bins, (int, np.integer)) or isinstance(n_bins, (bool, np.bool_)) or n_bins <= 0:
        raise ValueError("n_bins must be a positive integer")
    if not np.isfinite(p).all() or np.any((p < 0.0) | (p > 1.0)):
        raise ValueError("probabilities must be finite and in [0,1]")
    if not np.isin(y, [0, 1]).all():
        raise ValueError("labels must be binary")
    if p.size == 0:
        return 0.0

    bin_ids = np.minimum((p * n_bins).astype(np.int64), n_bins - 1)

    ece = 0.0
    n = p.size
    for b in range(n_bins):
        m = bin_ids == b
        count = int(m.sum())
        if count == 0:
            continue
        mean_prob = float(p[m].mean())
        mean_label = float(y[m].mean())
        ece += (count / n) * abs(mean_prob - mean_label)

    return float(ece)

import numpy as np

def hungarian_assignment(cost_matrix: np.ndarray) -> list[tuple[int, int]]:
    cost = np.asarray(cost_matrix, dtype=np.float64)
    if cost.ndim != 2:
        raise ValueError("cost_matrix must be 2D")
    if not np.isfinite(cost).all():
        raise ValueError("cost_matrix must contain only finite values")

    n0, m0 = cost.shape
    if n0 == 0 or m0 == 0:
        return []

    transposed = False
    if n0 > m0:
        cost = cost.T
        transposed = True

    n, m = cost.shape
    u = np.zeros(n + 1, dtype=np.float64)
    v = np.zeros(m + 1, dtype=np.float64)
    p = np.zeros(m + 1, dtype=np.int64)
    way = np.zeros(m + 1, dtype=np.int64)

    for i in range(1, n + 1):
        p[0] = i
        j0 = 0
        minv = np.full(m + 1, np.inf, dtype=np.float64)
        used = np.zeros(m + 1, dtype=bool)

        while True:
            used[j0] = True
            i0 = p[j0]
            delta = np.inf
            j1 = 0

            for j in range(1, m + 1):
                if used[j]:
                    continue
                cur = cost[i0 - 1, j - 1] - u[i0] - v[j]
                if cur < minv[j]:
                    minv[j] = cur
                    way[j] = j0
                if minv[j] < delta:
                    delta = minv[j]
                    j1 = j

            for j in range(m + 1):
                if used[j]:
                    u[p[j]] += delta
                    v[j] -= delta
                else:
                    minv[j] -= delta

            j0 = j1
            if p[j0] == 0:
                break

        while True:
            j1 = way[j0]
            p[j0] = p[j1]
            j0 = j1
            if j0 == 0:
                break

    pairs = []
    for j in range(1, m + 1):
        if p[j] != 0:
            r = int(p[j] - 1)
            c = int(j - 1)
            pairs.append((c, r) if transposed else (r, c))

    pairs.sort()
    return pairs

import numpy as np

def temporal_mask_smooth(masks: np.ndarray, window_size: int) -> np.ndarray:
    x = np.asarray(masks)
    if x.ndim != 3:
        raise ValueError("masks must have shape (T,H,W)")
    if not isinstance(window_size, (int, np.integer)) or isinstance(window_size, (bool, np.bool_)):
        raise ValueError("window_size must be an odd positive integer")
    if window_size <= 0 or window_size % 2 == 0:
        raise ValueError("window_size must be an odd positive integer")
    if not np.isin(x, [0, 1]).all():
        raise ValueError("masks must be binary")

    t, h, w = x.shape
    if t == 0:
        return x.copy()
    if t == 1:
        return x.copy()

    pad = window_size // 2
    padded = np.pad(x.astype(np.float64), ((pad, pad), (0, 0), (0, 0)), mode="reflect")

    smoothed_mean = np.zeros((t, h, w), dtype=np.float64)
    for i in range(window_size):
        smoothed_mean += padded[i:i + t]
    smoothed_mean /= window_size

    out = (smoothed_mean >= 0.5).astype(x.dtype)

    change = np.zeros_like(x, dtype=bool)
    change[1:] |= x[1:] != x[:-1]
    change[:-1] |= x[:-1] != x[1:]
    out[change] = x[change]

    return out

import math

def cosine_annealing_warm_restarts(steps: list[int], lr0: float, lr_min: float, T_0: int, T_mult: float) -> list[float]:
    if not isinstance(T_0, int) or isinstance(T_0, bool) or T_0 <= 0:
        raise ValueError("T_0 must be a positive integer")
    if not math.isfinite(T_mult) or T_mult < 1.0:
        raise ValueError("T_mult must be finite and >= 1")
    if not (math.isfinite(lr0) and math.isfinite(lr_min)):
        raise ValueError("learning rates must be finite")

    out = []
    for step in steps:
        if not isinstance(step, int) or isinstance(step, bool) or step < 0:
            raise ValueError("steps must be non-negative integers")

        if T_mult == 1.0:
            T_i = float(T_0)
            t_cur = float(step % T_0)
        else:
            start = 0.0
            T_i = float(T_0)
            s = float(step)
            while s >= start + T_i:
                start += T_i
                T_i *= T_mult
            t_cur = s - start

        lr = lr_min + 0.5 * (lr0 - lr_min) * (1.0 + math.cos(math.pi * t_cur / T_i))
        out.append(float(lr))

    return out
